'use client';

import { forwardRef, type ButtonHTMLAttributes, type CSSProperties } from 'react';
import './rolling-text-button.css';

export interface RollingTextButtonProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children'> {
  /** A plain-text label. Its decorative letters roll while its accessible name stays fixed. */
  children: string;
}

/** A typographic action with a staggered, vertical letter roll. */
export const RollingTextButton = forwardRef<HTMLButtonElement, RollingTextButtonProps>(
  function RollingTextButton(
    { children, className = '', type = 'button', disabled = false, ...props },
    ref,
  ) {
    let letterIndex = 0;

    return (
      <button
        {...props}
        ref={ref}
        type={type}
        disabled={disabled}
        className={`ac-rolling-text ${className}`.trim()}
      >
        <span className="ac-rolling-text__accessible">{children}</span>
        <span className="ac-rolling-text__visual" aria-hidden="true">
          {children.split(/(\s+)/).map((word, wordIndex) => {
            if (!word || /^\s+$/.test(word)) return word;

            return (
              <span key={wordIndex} className="ac-rolling-text__word">
                {Array.from(word).map((character, index) => {
                  const delay = Math.min(letterIndex++, 16) * 16;

                  return (
                    <span
                      key={index}
                      className="ac-rolling-text__window"
                      style={{ '--ac-roll-delay': `${delay}ms` } as CSSProperties}
                    >
                      <span className="ac-rolling-text__glyph">{character}</span>
                      <span className="ac-rolling-text__glyph">{character}</span>
                    </span>
                  );
                })}
              </span>
            );
          })}
        </span>
      </button>
    );
  },
);

export default RollingTextButton;

.ac-rolling-text {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 44px;
  min-height: 50px;
  max-width: 100%;
  box-sizing: border-box;
  padding: 0.95em 1.5em;
  border: 1px solid var(--ac-roll-border, #263629);
  border-radius: var(--ac-roll-radius, 6px);
  background: var(--ac-roll-bg, #263629);
  color: var(--ac-roll-color, #f2f6ea);
  font: inherit;
  font-size: 0.95rem;
  font-weight: 550;
  line-height: 1.15;
  text-align: center;
  text-decoration: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
  transition: background-color 180ms ease, box-shadow 180ms ease;
}

.ac-rolling-text__accessible {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  padding: 0;
  border: 0;
  white-space: nowrap;
  clip: rect(0, 0, 0, 0);
  clip-path: inset(50%);
}

.ac-rolling-text__visual {
  display: block;
  min-width: 0;
  max-width: 100%;
  white-space: normal;
  pointer-events: none;
}

.ac-rolling-text__word {
  display: inline-block;
  max-width: 100%;
  vertical-align: top;
}

.ac-rolling-text__window {
  display: inline-block;
  height: 1.15em;
  overflow: hidden;
  vertical-align: top;
}

.ac-rolling-text__glyph {
  display: block;
  height: 1.15em;
  line-height: 1.15;
  transition: transform 340ms cubic-bezier(0.22, 0.7, 0.18, 1);
  transition-delay: var(--ac-roll-delay, 0ms);
}

.ac-rolling-text:not(:disabled):focus-visible {
  outline: 2px solid var(--ac-roll-focus, #6c8c44);
  outline-offset: 4px;
}

.ac-rolling-text:not(:disabled):focus-visible .ac-rolling-text__glyph {
  transform: translateY(-100%);
}

@media (hover: hover) and (pointer: fine) {
  .ac-rolling-text:not(:disabled):hover {
    background: var(--ac-roll-hover-bg, #3b513a);
  }

  .ac-rolling-text:not(:disabled):hover .ac-rolling-text__glyph {
    transform: translateY(-100%);
  }
}

.ac-rolling-text:not(:disabled):active {
  background: var(--ac-roll-active-bg, #1a281b);
  box-shadow: inset 0 0 0 2px var(--ac-roll-press-ring, #ffffff33);
}

.ac-rolling-text:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.ac-rolling-text:disabled,
.ac-rolling-text:disabled .ac-rolling-text__glyph {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .ac-rolling-text,
  .ac-rolling-text__glyph {
    transition: none;
  }

  .ac-rolling-text .ac-rolling-text__glyph {
    transform: none !important;
  }
}
